test('default collect scope stays native even under a Desktop caller',t=>{
  const f=fixture(t),calls=[];
  const r=collect({...f,installed,run:(exe,args,options)=>{calls.push(options.env);return response(args[2]);}});
  assert.equal(r.scope,'native');
  assert.equal(r.coverage.length,2);
  assert.equal(calls.some(env=>env.CODEX_HOME.includes(f.desktopHome)),false);
});
